corrected_code:
package graph

import (
	"context"
	"errors"
	"myapp/auth"
	"myapp/graph/model"
)

func (r *QueryResolver) UserSupportTicket(ctx context.Context, ticketID string) (*model.SupportTicket, error) {
	user, ok := auth.UserFromContext(ctx)
	if !ok {
		return nil, errors.New("unauthenticated")
	}

	ticket, err := r.TicketService.FindByID(ctx, ticketID)
	if err != nil {
		return nil, err
	}

	if ticket.CustomerID != user.ID && !user.IsSupportAgent {
		return nil, errors.New("access denied to support ticket")
	}

	return ticket, nil
}
